[Operator comparison with explicit trace dependence]
\label{the:operator_profile_comparison}
For every deterministic $A\in\mathcal M_p$ and every $q\geq1$,
\begin{align}
 &\|\tr(A(G^z-\tilde G^z))\|_{L^q}
 =O\left(|A|_{\op}
 \left(1+\frac{|\Sigma|_*^\infty}n\right)^{3/2}
 \tau_\Sigma\bigl(1+M_{\op}^{(q)}\bigr)\right).
\end{align}
For every $q\geq2$, one also has
\begin{align}
 &\|\tr(A(G^z-\tilde G^z))\|_{L^q}
 =O\left(|A|_{\op}
 \left(1+\frac{|\Sigma|_*^\infty}n\right)^{3/2}\left[
 \frac{\tau_\Sigma M_{\op}^{(q)}}{\sqrt n}
 +\frac{\tau_\Sigma^2+(M_{\op}^{(2)})^2}{n}
 \right]\right).
\end{align}
If $K\subset(-\infty,0)$, the factor
$\left(1+\frac{|\Sigma|_*^\infty}{n}\right)^{3/2}$ in both bounds may be
replaced by $1+\frac{|\Sigma|_*^\infty}{n}$.

[Hilbert--Schmidt comparison under a profile bound]
\label{the:noncommuting_limited_second_moment_profiles}
Assume that
\begin{align}\label{eq:hs_profile_size_condition}
    \sqrt p\,|\Sigma|_{\hs}^\infty=O(n).
\end{align}
For every deterministic $A\in\mathcal M_p$ and every $q\geq1$,
\begin{align}\label{eq:noncommuting_limited_second_moment_uniform}
    \left\|
        \tr\left(A(G^z-\tilde G^z)\right)
    \right\|_{L^q}
    &={}
    O\left(
        \sigma_\Sigma|A|_{\hs}\left[
            M_{\hs}^{(q)}+\frac{|\Sigma|_{\hs}^\infty}n
        \right]
    \right).
\end{align}
For every $q\geq2$,
\begin{align}\label{eq:noncommuting_limited_second_moment_refined}
    \left\|
        \tr\left(A(G^z-\tilde G^z)\right)
    \right\|_{L^q}
    &={}
    O\left(
        |A|_{\hs}
        \left[
            \frac{M_{\hs}^{(q)}}{\sqrt n}
            +\sigma_\Sigma
             \frac{|\Sigma|_{\hs}^\infty+(M_{\hs}^{(2)})^2\sqrt p}{n}
        \right]
    \right).
\end{align}

[Random-to-deterministic resolvent sandwiches]
\label{cor:resolvent_sandwich_comparison}
Let $A,B\in\mathcal M_p$ be deterministic, and let $q\geq1$. In each of the
minima below, the second entry is available only when $q\geq2$.

\begin{enumerate}
\item[\textnormal{(i)}]
$\begin{aligned}[t]
&\left\|
    \tr\!\left(
        B\left[
            \mathcal S^z[A]
            -\widetilde{\mathcal S}^{\,z}[A]
        \right]
    \right)
\right\|_{L^q}
\nonumber\\
&\quad=
O\!\Biggl(
    |A|_{\op}|B|_{\op}
    \left(1+\frac{|\Sigma|_*^\infty}{n}\right)^{3/2}
    \min\left\{
        \tau_\Sigma\bigl(1+M_{\op}^{(q)}\bigr),
        \frac{\tau_\Sigma M_{\op}^{(q)}}{\sqrt n}
        +\frac{\tau_\Sigma^2+(M_{\op}^{(2)})^2}{n}
    \right\}
\Biggr).
\end{aligned}$

\item[\textnormal{(ii)}]
If $\sqrt p\,|\Sigma|_{\hs}^\infty=O(n)$,
then
\begin{align*}
&\left\|
    \tr\!\left(
        B\left[
            \mathcal S^z[A]
            -\widetilde{\mathcal S}^{\,z}[A]
        \right]
    \right)
\right\|_{L^q}
\nonumber\\
&\quad=
O\!\Biggl(
    |A|_{\op}|B|_{\hs}
    \min\left\{
        \sigma_\Sigma
        \left(
            M_{\hs}^{(q)}
            +\frac{|\Sigma|_{\hs}^\infty}{n}
        \right),
        \frac{M_{\hs}^{(q)}}{\sqrt n}
        +\sigma_\Sigma
        \frac{
            |\Sigma|_{\hs}^\infty
            +(M_{\hs}^{(2)})^2\sqrt p
        }{n}
    \right\}
\Biggr).

\end{align*}
\end{enumerate}

[Aperture of an admissible matrix sector]
\label{lem:matrix_parameter_sector_aperture}
For every admissible matrix \(Z\), the cone \(\mathcal C_Z\) is closed,
and the principal arguments of its nonzero elements form the closed interval
\([\theta_Z^-,\theta_Z^+]\), with \(\theta_Z^-\leq0\leq\theta_Z^+\) and
\begin{align}\label{eq:matrix_parameter_sector_aperture}
    0\leq\theta_Z^+-\theta_Z^-
    \leq2\arccos\left(\frac{\eta_Z}{2|Z|_{\op}}\right)<\pi.
\end{align}

[Supporting phase for an admissible parameter]
\label{lem:matrix_parameter_supporting_phase}
For every admissible matrix \(Z\), the phase and constant in
\eqref{eq:matrix_parameter_angular_phase} satisfy
\begin{align}
    \Re(\overline{\omega_Z}u)\geq c_Z|u|,
    \qquad u\in\mathcal C_Z,
\end{align}
and
\begin{align}\label{eq:matrix_parameter_coercivity}
    \Re(\overline{\omega_Z}(-Z))
    \succeq c_Z\eta_Z I_p\succ0.
\end{align}

[Weighted secant estimate]
\label{lem:weighted_secant_estimate}
For \(D,D'\in\mathcal D_n(\mathcal C_Z\setminus\{0\})\) and every
\(u\in\mathbb C^n\),
\begin{multline}\label{eq:weighted_secant_estimate}
    |\Psi^Z(D,D')u|_{D,D'}
    \leq
    \max_{i\in[n]}
    \sqrt{
        \frac{|D_i|^2\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_D^Z)\right)}{\mathfrak C_Z(D_i)}
        \frac{|D_i'|^2\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_{D'}^Z)\right)}{\mathfrak C_Z(D_i')}
    }
    |u|_{D,D'}.
\end{multline}
The quantities
\(\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_D^Z)\right)\)
are nonnegative.

[Fixed-point secant contraction and uniqueness]
\label{pro:fixed_point_secant_contraction}
If \(D,D'\in\mathcal D_n(\mathcal C_Z)\) are fixed points of \(\Phi^Z\),
then
\begin{equation}\label{eq:fixed_point_secant_contraction}
    |\Psi^Z(D,D')|_{D,D'}
    \leq
    \max_{i\in[n]}
    \sqrt{
        \frac{\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_D^Z)\right)}{\mathfrak C_Z(1)+\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_D^Z)\right)}
        \frac{\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_{D'}^Z)\right)}{\mathfrak C_Z(1)+\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_{D'}^Z)\right)}
    }
    <1.
\end{equation}
Consequently, the fixed point is unique in
\(\mathcal D_n(\mathcal C_Z)\), and
\(I_n-\Psi^Z(D,D)\) is invertible.

[Mean Hilbert--Schmidt leave-one-out bound]
\label{lem:leave_one_out_profile_bounds}
For every $i\in[n]$,
\begin{align}\label{eq:leave_one_out_hs_profile_bound}
    |\mathbb E[G-G_{-i}]|_{\hs}
    = O\left(\frac{|\Sigma_i|_{\hs}}n\right).
\end{align}

[Inverse-defect transfer for negative Hermitian parameters]
\label{cor:negative_hermitian_inverse_defect_transfer}
Let \(Z\in\mathcal K\) satisfy \(Z=Z^*\prec0\), and let
\(D\in\mathcal D_n((0,\infty))\). Then
\begin{align}
    |G_D^Z-\widetilde G^Z|_*
    \leq
    \frac1{\eta_Z}
    \sum_{i=1}^n|D_i r_i(D)|.
\end{align}
The coefficient $\eta_Z^{-1}$ is uniformly bounded on $\mathcal K$
by \eqref{eq:common_probabilistic_sector_bounds}.

[Bias and inverse defect of the check pivot]
\label{pro:interaction_controlled_check_pivot}
Assume that $\sqrt p\,|\Sigma|_{\hs}^\infty=O(n)$. Then
\begin{align}
 |\mathbb E[G^Z]-\check G^Z|_{\hs}
 &=O\left(J(\check\Delta)\left[
 \frac{|\Sigma|_{\hs}^\infty}n
 +\min\left\{
   M_{\hs}^{(1)},
   \frac{(M_{\hs}^{(2)})^2\sqrt p}{n}
 \right\}\right]\right),
 \label{eq:interaction_check_bias}\\
 |r(\check\Delta)|_\infty
 &=O\left(\frac{|\Sigma|_{\hs}^\infty}nJ(\check\Delta)\left[
 \frac{|\Sigma|_{\hs}^\infty}n
 +\min\left\{
   M_{\hs}^{(1)},
   \frac{(M_{\hs}^{(2)})^2\sqrt p}{n}
 \right\}\right]\right).
 \label{eq:interaction_check_defect}
\end{align}

[Hilbert--Schmidt comparison]
\label{pro:sigma_profile_hs_comparison}
Assume that $\sqrt p\,|\Sigma|_{\hs}^\infty=O(n)$, and let
$Z\in\mathcal K$ satisfy $|Z|_{\op}=O(1)$.
For every deterministic $A\in\mathcal M_p$,
\begin{align*}
 \left|\tr\left(A(\mathbb E[G^Z]-\widetilde G^Z)\right)\right|
 &=O\left(\sigma_\Sigma|A|_{\hs}\left[
 \frac{|\Sigma|_{\hs}^\infty}n
 +\min\left\{
 M_{\hs}^{(1)},
 \frac{(M_{\hs}^{(2)})^2\sqrt p}{n}
 \right\}\right]\right).
\end{align*}

[Expected pivots and partial pivot sums]
\label{lem:operator_expected_pivots}
Every convex average $d$ of the numbers $(\mathbb E[\Delta_i])_{i\in[N]}$ belongs to
$\mathcal C_Z\setminus\{0\}$ and satisfies
\[
 |d|=O(1),\qquad |d|^{-1}=O(\rho_\Sigma).
\]
Moreover, for every deterministic $I\subset[N]$ and $q\geq1$,
\begin{align}\label{eq:partial_schur_pivot_concentration}
 \left\|\sum_{i\in I}(\Delta_i-\mathbb E\Delta_i)\right\|_{L^q}
 =O\!\left(c_{N,q}M_{\op}^{(q)}\right).
\end{align}

[One-class comparison in a bounded sectorial background]
\label{pro:one_class_sectorial_comparison}
Assume that $\Sigma_i=\Sigma$ for every $i\in[N]$, and let
$Z\in\mathcal K$ satisfy $|Z|_{\op}=O(1)$.
For every $q\in\{1,2\}$ such that $M_{\op}^{(q)}<\infty$,
\begin{equation}
\label{eq:common_sectorial_bias}
    |\mathbb EG-\widehat G|_*
    =
    O\!\left(
        \frac{\rho_\Sigma}{N^{q-1}}
        \bigl(
            \min\{1,|\Sigma|_{\op}\}
            +M_{\op}^{(q)}
        \bigr)^q
    \right).
\end{equation}

[Spectral spread from quadratic-form fluctuations]
\label{lem:quadratic_form_spectral_spread}
Let $x\in\mathbb R^p$ have finite second moments. Then
\begin{align*}
    |\Sigma|_{\hs} 
    \leq|\Sigma|_{\op}  + \sup_{|B|_{\op}\leq1}
    \left\|x^\top Bx-\tr(\Sigma B)\right\|_{L^2},
    \qquad \Sigma:=\mathbb E[xx^\top].
\end{align*}

[Iterated pivots]
\label{lem:class_average_pivot_estimates}
For every \(\ell\in[k]\), \(Z^{(\ell)}\in \mathcal K_p\) and
\(Z_{\mathcal F^{\ell}}^{(\ell)}\in \mathcal K_p\).
All stage resolvents are well defined. Moreover, $\widehat\delta_{\mathcal F^{\ell}}^{(\ell)},
    \widehat\delta^{(\ell)}
    \in\mathcal C_Z\setminus\{0\}$, and
\[
    \left|
        \widehat\delta_{\mathcal F^{\ell}}^{(\ell)}
    \right|
    +
    \left|
        \widehat\delta^{(\ell)}
    \right|
    =
    O(1),
    \qquad
    \left|
        \widehat\delta_{\mathcal F^{\ell}}^{(\ell)}
    \right|^{-1}
    +
    \left|
        \widehat\delta^{(\ell)}
    \right|^{-1}
    =
    O(\rho_\Sigma).
\]
In addition,
\begin{align}
\label{eq:class_pivot_first_moment}
    n_{\ell}
    \left\|
        \widehat\delta_{\mathcal F^{\ell}}^{(\ell)}
        -
        \widehat\delta^{(\ell)}
    \right\|_{L^1}
    &=
    O\!\left(
        \pi_{\ell}\tau_\Sigma M_{\op}^{(1)}
    \right),
    \\
\label{eq:class_pivot_second_moment}
    n_{\ell}
    \left\|
        \widehat\delta_{\mathcal F^{\ell}}^{(\ell)}
        -
        \widehat\delta^{(\ell)}
    \right\|_{L^2}
    &=
    O\!\left(
        \pi_{\ell}
        \left[
            \frac{\tau_\Sigma M_{\op}^{(2)}}{\sqrt n}
            +
            \frac{(M_{\op}^{(2)})^2}{n}
        \right]
    \right).
\end{align}
If \(Z=Z^*\prec0\), all stage resolvents are positive definite and all
stage pivots are positive.

\label{pro:classwise_averaged_pivot_comparison}
Let $Z\in\mathcal K$ satisfy $|Z|_{\op}=O(1)$. Then
\begin{equation}
    |\mathbb E[G^Z]-\widehat G|_*
    =O\!\left(\rho_\Sigma\varepsilon\right).
\end{equation}

[Weighted inverse defect]
\label{lem:classwise_weighted_inverse_defect}
Let $Z\in\mathcal K$ satisfy $|Z|_{\op}=O(1)$. Then
\begin{equation}
    \sum_{i=1}^n|\widehat\Delta_i r_i(\widehat\Delta)|
    =O\!\left(\rho_\Sigma\varepsilon\right).
\end{equation}

[Classwise comparison with the fixed-point resolvent]
\label{pro:classwise_operator_profile_comparison}
Let $Z\in\mathcal K$ satisfy $|Z|_{\op}=O(1)$. Then
\begin{equation}
\label{eq:tau_operator_bias}
    |\mathbb E[G^Z]-\widetilde G^Z|_*
    =O\!\left(\rho_\Sigma^{3/2}\varepsilon\right).
\end{equation}
If $Z=Z^*\prec0$, one can replace $\rho_\Sigma^{3/2}$ by $\rho_\Sigma$ in this bound.

[Deterministic equivalent of the resolvent sandwich]
\label{pro:deterministic_linear_response_equation}
For every $z\in\Omega$ and every deterministic matrix $A\in\mathcal M_p$,
the linear fixed-point equation
\eqref{eq:deterministic_linear_response_equation} has a unique solution, and
\begin{align}
    \widetilde{\mathcal S}^{\,z}[A]
    =
    -\left.
    \frac{\mathrm d}{\mathrm dt}
    \widetilde G^{Z_t}
    \right|_{t=0}.
\end{align}
The solution depends complex-linearly on $A$. Moreover, $\widetilde{\mathcal S}^{\,\bar z}[\overline A]
    =\overline{\widetilde{\mathcal S}^{\,z}[A]}$.

[Martingale replacement-moment inequality]
\label{the:efron_stein_Lq_simple}
If $1\leq q\leq2$, then
\[
    \|F-\mathbb E[F]\|_{L^q}
    = O\!\left(
      \left(\sum_{i=1}^n\|F-F^{(i)}\|_{L^q}^q\right)^{1/q}
    \right)
    = O\!\left(
      n^{1/q}\sup_{i\in[n]}\|F-F^{(i)}\|_{L^q}
    \right).
\]
If $q\geq2$, then
\[
    \|F-\mathbb E[F]\|_{L^q}
    = O\!\left(
      \left(\sum_{i=1}^n\|F-F^{(i)}\|_{L^q}^2\right)^{1/2}
    \right)
    = O\!\left(
      \sqrt n\sup_{i\in[n]}\|F-F^{(i)}\|_{L^q}
    \right).
\]

[Reciprocal difference estimate]
\label{lem:reciprocal_difference_estimate}
Let $s$ and $t$ be integrable complex random variables, with $s,t\in L^2$
for the second estimate. If
\[
    \left|1+\frac{\mathbb E[t]}n\right|^{-1}
    =O(1),
    \qquad
    \left|1+\frac tn\right|^{-1}
    =O(1)
\]
almost surely, then
\begin{align*}
    \left|
      \mathbb E\left[
        s\left(
          \frac1{1+\mathbb E[t]/n}
          -
          \frac1{1+t/n}
        \right)
      \right]
    \right|
    &=
    O\left(
       \|s-\mathbb E[s]\|_{L^1}
       +\frac{|\mathbb E[s]|}{n}
        \|t-\mathbb E[t]\|_{L^1}
    \right),
    \\
    \left|
      \mathbb E\left[
        s\left(
          \frac1{1+\mathbb E[t]/n}
          -
          \frac1{1+t/n}
        \right)
      \right]
    \right|
    &=
    O\left(
       \frac{\|s-\mathbb E[s]\|_{L^2}
             \|t-\mathbb E[t]\|_{L^2}}{n}
       +\frac{|\mathbb E[s]|
             \|t-\mathbb E[t]\|_{L^2}^2}{n^2}
    \right).
\end{align*}

[Complex and conditional test reduction]
\label{lem:complex_conditional_test_reduction}
Let $x\in\mathbb R^p$ have finite second moments, and set $\Sigma:=\mathbb E[xx^\top]$. Then  \begin{align*}
    x^{\top}Bx-\tr(\Sigma B)
    &=x^{\top}B_{\mathrm s}x-\tr(\Sigma B_{\mathrm s}),
    \qquad 
    |B_{\mathrm s}|_{\op}&\leq|B|_{\op},
    \qquad
    |B_{\mathrm s}|_{\hs}&\leq|B|_{\hs}.
\end{align*}

[Geometry of the two test balls]
\label{lem:quadratic_form_test_ball_geometry}
For every real symmetric positive semidefinite matrix
$\Sigma\in\mathcal M_p$,
\begin{align*}
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\hs}\leq1}}
    |\Sigma^{1/2}B_{\mathrm s}\Sigma^{1/2}|_{\hs}
    &=|\Sigma|_{\op},
    &
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\op}\leq1}}
    |\Sigma^{1/2}B_{\mathrm s}\Sigma^{1/2}|_{\hs}
    &=|\Sigma|_{\hs}.
\end{align*}

[Independent-coordinate quadratic-form moduli]
\label{lem:profile_quadratic_form_moduli}
Let $x\in\mathbb R^p$ have second-moment matrix
$\Sigma:=\mathbb E[xx^\top]$, and assume that $x=\Sigma^{1/2}y$,
where $y$ has independent, centered, standardized coordinates.
If
\[
    K_4:=\sup_{j\in[p]}\|y_j\|_{L^4}<\infty,
\]
then
\begin{align*}
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\hs}\leq1}}
    \left\|x^\top Bx-\tr(\Sigma B)\right\|_{L^2}
    &=O\!\left(K_4^2|\Sigma|_{\op}\right),
    \\
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\op}\leq1}}
    \left\|x^\top Bx-\tr(\Sigma B)\right\|_{L^2}
    &=O\!\left(K_4^2|\Sigma|_{\hs}\right).
\end{align*}

[Gaussian quadratic-form moduli]
\label{lem:gaussian_quadratic_form_moduli}
Let $x\sim\mathcal N(0,\Sigma)$, where $\Sigma\in\mathcal M_p$ is real
symmetric and positive semidefinite.  For every fixed $q\geq2$,
\begin{align}
    \sqrt2|\Sigma|_{\op}
    &\leq
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\hs}\leq1}}
    \left\|x^{\top}Bx-\tr(\Sigma B)\right\|_{L^q}
    = O(|\Sigma|_{\op}),
    \label{eq:gaussian_hs_test_ball_exact_scale}
    \\
    \sqrt2|\Sigma|_{\hs}
    &\leq
    \sup_{\substack{B\in\mathcal M_p\\|B|_{\op}\leq1}}
    \left\|x^{\top}Bx-\tr(\Sigma B)\right\|_{L^q}
    = O(|\Sigma|_{\hs}).
    \label{eq:gaussian_operator_test_ball_exact_scale}
\end{align}
For \(q=2\), both lower bounds are equalities.

\begin{align}\label{eq:def_profile_hs_infty}
    |\Sigma|_\nu^\infty:=\max_{i\in[n]}|\Sigma_i|_\nu,
    \qquad \nu\in\{\op,\hs,*\}.
\end{align}

\begin{align}\label{eq:relation_mu_mu_i}
      \tilde\mu
      =\left(1-\frac np\right)\delta_0
       +\frac1p\sum_{i=1}^n\tilde\mu_i.    
  \end{align}

\begin{align}\label{eq:def_M_hs_op_main}
    M_{\hs}^{(q)}
    :=
    \sup_{\genfrac{}{}{0pt}{2}{i\in[n]}{|B|_{\hs}\leq1}}
    \left\|x_i^\top Bx_i-\tr(\Sigma_iB)\right\|_{L^q},
    \qquad
    M_{\op}^{(q)}
    :=
    \sup_{\genfrac{}{}{0pt}{2}{i\in[n]}{|B|_{\op}\leq1}}
    \left\|x_i^\top Bx_i-\tr(\Sigma_iB)\right\|_{L^q}.
\end{align}

\begin{align}\label{eq:def_tau_profile}
 \tau_\Sigma:=\max_{a\in[k]}
 \frac{1+|\Sigma^{(a)}|_{\op}}{1+\pi_a|\Sigma^{(a)}|_{\op}}.
\end{align}

\begin{align}\label{eq:def_sigma_profile}
    \sigma_\Sigma
    &:={}
    \inf_{\substack{
        T_1,\ldots,T_n\in\mathcal M_p(\mathbb R)\\
        T_i=T_i^\top\succeq0\ (i\in[n])\\
        T_iT_j=T_jT_i\ (i,j\in[n])
    }}
    \left(
        1+\dim_{\mathbb R}
        \operatorname{span}\{T_1,\ldots,T_n\}
    \right)
    \left(
        1+\frac1n\sum_{i=1}^n|\Sigma_i-T_i|_{\op}
    \right).
\end{align}

\begin{align}\label{eq:hs_profile_size_condition}
    \sqrt p\,|\Sigma|_{\hs}^\infty=O(n).
\end{align}

\begin{align}\label{eq:noncommuting_limited_second_moment_uniform}
    \left\|
        \tr\left(A(G^z-\tilde G^z)\right)
    \right\|_{L^q}
    &={}
    O\left(
        \sigma_\Sigma|A|_{\hs}\left[
            M_{\hs}^{(q)}+\frac{|\Sigma|_{\hs}^\infty}n
        \right]
    \right).
\end{align}

\begin{align}\label{eq:noncommuting_limited_second_moment_refined}
    \left\|
        \tr\left(A(G^z-\tilde G^z)\right)
    \right\|_{L^q}
    &={}
    O\left(
        |A|_{\hs}
        \left[
            \frac{M_{\hs}^{(q)}}{\sqrt n}
            +\sigma_\Sigma
             \frac{|\Sigma|_{\hs}^\infty+(M_{\hs}^{(2)})^2\sqrt p}{n}
        \right]
    \right).
\end{align}

\begin{align}
\label{eq:deterministic_linear_response_equation}
    \widetilde{\mathcal S}^{\,z}[A]
    ={}&
    \tilde G^z A\tilde G^z
    +
    \frac1{n^2}\sum_{i=1}^n
    \frac{
        \tr\!\left(
            \Sigma_i\widetilde{\mathcal S}^{\,z}[A]
        \right)
    }{
        \left(
            1+\frac1n\tr(\Sigma_i\tilde G^z)
        \right)^2
    }
    \tilde G^z\Sigma_i\tilde G^z.
\end{align}

\begin{equation}
\label{eq:square_summable_profile_operator_rate}
    \left\|\tr\!\left(A(G^z-\tilde G^z)\right)\right\|_{L^q}
    =O\!\left(\frac{|A|_{\op}}{\sqrt n}\right),
    \qquad q\geq2,
\end{equation}

\begin{align}\label{eq:def_matrix_resolvent_sector}
    \mathcal C_Z:=\cone\bigl(\mathbb R_+\cup-\mathcal W(Z)\bigr).
\end{align}

\begin{align}\label{eq:matrix_parameter_sector_aperture}
    0\leq\theta_Z^+-\theta_Z^-
    \leq2\arccos\left(\frac{\eta_Z}{2|Z|_{\op}}\right)<\pi.
\end{align}

\begin{align}\label{eq:matrix_parameter_coercivity}
    \Re(\overline{\omega_Z}(-Z))
    \succeq c_Z\eta_Z I_p\succ0.
\end{align}

\begin{equation}\label{eq:sectorial_resolvent_hypotheses}
    \forall v\in \mathcal C_Z:\quad \Re(\overline{\omega}v)\geq c|v|
    \qquad
    \text{and}
    \qquad
    \Re(\overline{\omega}(-Z))\succeq\kappa I_p.
\end{equation}

\begin{equation}\label{eq:matrix_parameter_deterministic_equation}
    \widetilde G^Z
    =
    \left(
        -Z+\frac1n\sum_{i=1}^n
        \frac{\Sigma_i}
        {1+\frac1n\tr(\Sigma_i\widetilde G^Z)}
    \right)^{-1}.
\end{equation}

\begin{equation}\label{eq:def_inverse_defect}
    r_i(D):=\frac1{D_i}-1-\frac1n\tr(\Sigma_iG_D^Z).
\end{equation}

\begin{align}\label{eq:two_profile_inverse_defect_secant}
    \bigl(I_n-\Psi^Z(D,D')\bigr)(D-D')
    =
    -DD'\bigl(r(D)-r(D')\bigr).
\end{align}

\begin{multline}\label{eq:weighted_secant_estimate}
    |\Psi^Z(D,D')u|_{D,D'}
    \leq
    \max_{i\in[n]}
    \sqrt{
        \frac{|D_i|^2\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_D^Z)\right)}{\mathfrak C_Z(D_i)}
        \frac{|D_i'|^2\frac1n\mathfrak C_{\bar Z}\!\left(\tr(\Sigma_iG_{D'}^Z)\right)}{\mathfrak C_Z(D_i')}
